// ImageLibrary.swift — the built-in key graphics plus whatever the user imports.
//
// Built-in icons live in the bundle (Resources/Library, generated by tools/make_library.py so every
// asset is original). Imported images are copied into Application Support/Deckhand/Library, which is
// also where "Choose Image" opens.
import Foundation
import SwiftUI

struct LibraryImage: Identifiable, Hashable {
    let id: String
    let url: URL
    let name: String
    let builtIn: Bool
}

@MainActor
final class ImageLibrary: ObservableObject {
    static let shared = ImageLibrary()

    @Published private(set) var builtIn: [LibraryImage] = []
    @Published private(set) var imported: [LibraryImage] = []

    static var userDirectory: URL {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("Deckhand", isDirectory: true)
        let lib = base.appendingPathComponent("Library", isDirectory: true)
        try? FileManager.default.createDirectory(at: lib, withIntermediateDirectories: true)
        return lib
    }

    private static var bundledDirectory: URL? {
        if let url = Bundle.main.resourceURL?.appendingPathComponent("Library", isDirectory: true),
           FileManager.default.fileExists(atPath: url.path) {
            return url
        }
        // running straight from the build directory (`swift run`, or the bare binary)
        let local = Bundle.main.bundleURL.deletingLastPathComponent()
            .appendingPathComponent("Resources/Library", isDirectory: true)
        return FileManager.default.fileExists(atPath: local.path) ? local : nil
    }

    init() { reload() }

    func reload() {
        builtIn = Self.scan(Self.bundledDirectory, builtIn: true)
        imported = Self.scan(Self.userDirectory, builtIn: false)
    }

    private static func scan(_ dir: URL?, builtIn: Bool) -> [LibraryImage] {
        guard let dir else { return [] }
        let keys: [URLResourceKey] = [.isRegularFileKey]
        let files = (try? FileManager.default.contentsOfDirectory(at: dir,
                                                                  includingPropertiesForKeys: keys,
                                                                  options: [.skipsHiddenFiles])) ?? []
        return files
            .filter { ["png", "jpg", "jpeg", "heic", "tiff"].contains($0.pathExtension.lowercased()) }
            .map { url in
                LibraryImage(id: (builtIn ? "builtin:" : "user:") + url.lastPathComponent,
                             url: url,
                             name: url.deletingPathExtension().lastPathComponent,
                             builtIn: builtIn)
            }
            .sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
    }

    /// Copy images the user picked into the library. Returns how many were added.
    @discardableResult
    func importImages(_ urls: [URL]) -> Int {
        var added = 0
        for url in urls {
            let scoped = url.startAccessingSecurityScopedResource()
            defer { if scoped { url.stopAccessingSecurityScopedResource() } }

            let ext = url.pathExtension.isEmpty ? "png" : url.pathExtension.lowercased()
            var target = Self.userDirectory.appendingPathComponent("\(url.deletingPathExtension().lastPathComponent).\(ext)")
            var n = 2
            while FileManager.default.fileExists(atPath: target.path) {
                target = Self.userDirectory.appendingPathComponent(
                    "\(url.deletingPathExtension().lastPathComponent) \(n).\(ext)")
                n += 1
            }
            if (try? FileManager.default.copyItem(at: url, to: target)) != nil {
                added += 1
                Log.write("library: imported \(target.lastPathComponent)")
            } else {
                Log.write("library: could not import \(url.lastPathComponent)")
            }
        }
        reload()
        return added
    }

    func delete(_ image: LibraryImage) {
        guard !image.builtIn else { return }
        try? FileManager.default.removeItem(at: image.url)
        reload()
    }
}

/// Grid of bundled + imported graphics. Picking one hands its file URL back to the caller.
struct LibraryPickerView: View {
    let title: String
    let onPick: (URL) -> Void
    let onCancel: () -> Void

    @StateObject private var library = ImageLibrary.shared
    @State private var query = ""

    private let columns = [GridItem(.adaptive(minimum: 84, maximum: 96), spacing: 12)]

    private var shownBuiltIn: [LibraryImage] {
        filter(library.builtIn)
    }
    private var shownImported: [LibraryImage] {
        filter(library.imported)
    }

    private func filter(_ images: [LibraryImage]) -> [LibraryImage] {
        let q = query.trimmingCharacters(in: .whitespaces)
        guard !q.isEmpty else { return images }
        return images.filter { $0.name.localizedCaseInsensitiveContains(q) }
    }

    var body: some View {
        VStack(spacing: 0) {
            HStack(spacing: 10) {
                Text(title)
                    .font(.headline)
                Spacer()
                Image(systemName: "magnifyingglass")
                    .foregroundStyle(.secondary)
                TextField("Search", text: $query)
                    .textFieldStyle(.roundedBorder)
                    .frame(width: 180)
            }
            .padding(.horizontal, 18)
            .padding(.vertical, 12)

            Divider()

            ScrollView {
                VStack(alignment: .leading, spacing: 18) {
                    if !shownBuiltIn.isEmpty {
                        section("Built-in", shownBuiltIn)
                    }
                    if !shownImported.isEmpty {
                        section("My Images", shownImported)
                    } else if library.imported.isEmpty {
                        VStack(alignment: .leading, spacing: 6) {
                            Text("My Images")
                                .font(.subheadline.weight(.semibold))
                                .foregroundStyle(.secondary)
                            Text("Nothing imported yet — use Import Images… below.")
                                .font(.callout)
                                .foregroundStyle(.secondary)
                        }
                    }
                }
                .padding(18)
            }

            Divider()

            HStack(spacing: 10) {
                Button {
                    importImages()
                } label: {
                    Label("Import Images…", systemImage: "square.and.arrow.down")
                }
                Button {
                    revealLibrary()
                } label: {
                    Label("Show Library in Finder", systemImage: "folder")
                }
                .labelStyle(.iconOnly)
                .help("Show the imported images in Finder")

                Spacer()

                Button("Cancel", role: .cancel) { onCancel() }
                    .keyboardShortcut(.cancelAction)
            }
            .padding(.horizontal, 18)
            .padding(.vertical, 12)
        }
        .frame(width: 660, height: 520)
    }

    private func section(_ name: String, _ images: [LibraryImage]) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(name)
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(.secondary)
            LazyVGrid(columns: columns, spacing: 12) {
                ForEach(images) { image in
                    Button {
                        onPick(image.url)
                    } label: {
                        VStack(spacing: 4) {
                            LibraryThumb(url: image.url)
                            Text(image.name)
                                .font(.caption2)
                                .foregroundStyle(.secondary)
                                .lineLimit(1)
                                .truncationMode(.middle)
                        }
                    }
                    .buttonStyle(.plain)
                    .help(image.name)
                }
            }
        }
    }

    private func importImages() {
        let panel = NSOpenPanel()
        panel.allowedContentTypes = [.image]
        panel.allowsMultipleSelection = true
        panel.canChooseDirectories = false
        panel.directoryURL = ImageLibrary.userDirectory
        panel.message = "Choose images to add to your library"
        guard panel.runModal() == .OK else { return }
        let added = library.importImages(panel.urls)
        Log.write("library: \(added) image(s) imported")
    }

    private func revealLibrary() {
        NSWorkspace.shared.activateFileViewerSelecting([ImageLibrary.userDirectory])
    }
}

private struct LibraryThumb: View {
    let url: URL

    var body: some View {
        // NSImage is cached by the system for the same URL, so this stays cheap in a scrolling grid
        if let image = NSImage(contentsOf: url) {
            Image(nsImage: image)
                .resizable()
                .interpolation(.high)
                .scaledToFill()
                .frame(width: 76, height: 76)
                .clipShape(RoundedRectangle(cornerRadius: 10))
                .overlay(RoundedRectangle(cornerRadius: 10).strokeBorder(.white.opacity(0.12)))
        } else {
            RoundedRectangle(cornerRadius: 10)
                .fill(.quaternary)
                .frame(width: 76, height: 76)
                .overlay(Image(systemName: "questionmark").foregroundStyle(.secondary))
        }
    }
}
